def recherche(mot, texte):
    m, n = len(mot), len(texte)
    decalage = {}
    for k in range(m - 1):
        decalage[mot[k]] = m - 1 - k
    i = 0
    while i <= n - m:
        j = m - 1
        while j >= 0 and texte[i + j] == mot[j]:
            j = j - 1
        if j < 0:
            return True
        i = i + decalage.get(texte[i + m - 1], m)
    return False

