def nombre_adherents(table, annee):
    compteur = 0
    for adherent in table:
        if adherent['annee'] == annee:
            compteur = compteur + 1
    return compteur

def adherent_plus_age(table):
    annee_min = '2025'
    for adherent in table:
        if adherent['annee'] < annee_min:
            annee_min = adherent['annee']
    plus_ages = []
    for adherent in table:
        if adherent['annee'] == annee_min:
            plus_ages.append(adherent)
    return plus_ages
